  timestamp: number;
}

interface MoneyWithdrawn {
  type: 'MoneyWithdrawn';
  accountId: string;
  amount: number;
  transactionId: string;
  timestamp: number;
}

type BankEvent = AccountOpened | MoneyDeposited | MoneyWithdrawn;

interface StoredEvent {
